static const fcn160_g_t *fcn160_find(unsigned cp) {
    int lo = 0, hi = (int)FCN160_N - 1;
    while (lo <= hi) {
        int mid = (lo + hi) >> 1;
        unsigned m = fcn160_dir[mid].cp;
        if (m == cp) return &fcn160_dir[mid];
        if (m < cp) lo = mid + 1; else hi = mid - 1;
    }
    return 0;
}
static void fcn160_glyph(int x, int y, const fcn160_g_t *g, uint32_t fg) {
    fg = fb_map(fg);
    const unsigned char *bm = fcn160_bits + g->off;
    int gx = x + g->xo, gy = y + g->yo;
    int idx = 0;
    for (int r = 0; r < g->h; r++) {
        for (int c = 0; c < g->w; c++) {
            unsigned a = (idx & 1) ? (bm[idx >> 1] & 0xF) : (bm[idx >> 1] >> 4);
            idx++;
            if (a) fcn_blend(gx + c, gy + r, a, fg);
        }
    }
}
static int fcn160_text(int x, int y, const char *s, uint32_t fg) {
    while (*s) {
        unsigned cp;
        int n = utf8_dec((const unsigned char *)s, &cp);
        const fcn160_g_t *g = fcn160_find(cp);
        if (g) { fcn160_glyph(x, y, g, fg); x += g->adv; }
        else if (cp < 0x80 && cp >= ' ') { x += FCN160_PX / 2; }
        s += n;
    }
    return x;
}
static int fcn160_w(const char *s) {
    int x = 0;
    while (*s) {
        unsigned cp;
        int n = utf8_dec((const unsigned char *)s, &cp);
        const fcn160_g_t *g = fcn160_find(cp);
        x += g ? g->adv : (cp < 0x80 && cp >= ' ' ? FCN160_PX / 2 : 0);
        s += n;
    }
    return x;
}
static void fcn160_center(int cx, int y, const char *s, uint32_t fg) {
    fcn160_text(cx - fcn160_w(s) / 2, y, s, fg);
}

